head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _2 : CSV 파일 선택 팝업창 옵션(useModalDisable, wframe). description 은 분리 샘플 공통.
scwin.tData = {
    "description" : "[gridView > M > readCSV]<br/>CSV 형식의 파일을 업로드하여 GridView 의 데이터로 설정합니다.",
    "validation" : [
        "useModalDisable(선택) 파라미터로 CSV 파일 선택 팝업창이 표시 될때 부모창의 비활성화 여부를 설정합니다.",
        "useModalDisable(선택) 파라미터를 'true' 로 설정 시 부모창을 비활성화 처리합니다.",
        "useModalDisable(선택) 파라미터를 'false' 로 설정 시 부모창을 비활성화 처리하지 않습니다.",
        "useModalDisable(선택) 파라미터를 생략하면 기본값 'false' 로 동작합니다.",
        "wframe 파라미터가 true 이면 useModalDisable 파라미터는 'false' 로 동작됩니다.",
        "useModalDisable(선택) 파라미터는 Boolean 이 아닌 String 형으로 'true' 를 설정하여야 적용됩니다.",
        "wframe(선택) 파라미터로 CSV 파일 선택 팝업창을 WFrame 으로 생성할지 여부를 설정합니다.",
        "wframe(선택) 파라미터를 true 로 설정 시 WFrame 으로 CSV 파일 선택 팝업창을 생성합니다.",
        "wframe(선택) 파라미터를 false 로 설정 시 별도의 팝업으로 CSV 파일 선택 팝업창을 생성합니다.",
        "wframe(선택) 파라미터를 생략하면 기본값 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : DataList 가 바인딩된 4 Column GridView 를 동적 생성한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name4 4개 Column 그리드에 초기 데이터 4행(col1_1 ~ col4_4)이 바인딩되어 있음\n- 테스트용 CSV : TSQA/src/sample/gridView/data/upload/ts_gridView_M_readCSV_2/ts_gridView_M_readCSV_2_upload.csv (0행 Header, 1~3행 데이터 csvA1~csvC4)\n[절차]\n1. par 옵션(useModalDisable / wframe) 값을 선택한다\n2. readCSV 버튼을 클릭한다\n3. 열린 업로드 창에서 CSV 파일을 선택하고 File Upload 를 실행한다\n4. 업로드결과확인 버튼을 클릭한다\n[확인]\n- 2번에서 업로드 창이 별도 브라우저 창으로 열리는지, 화면 내 WFrame 레이어로 열리는지 확인\n- 2번 직후 결과창에 팝업창 종류와 부모창 모달(비활성화) 레이어 개수가 출력됨\n- 2번 직후 부모 화면의 버튼/옵션이 클릭 가능한지로 부모창 비활성화 여부를 확인"', '', 'label1');

    // DataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (DataList 바인딩)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id
    });
    await $c.gcm.createBasicGridView(cList);
}



// par 옵션값으로 readCSV options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · useModalDisable 은 String 형과 Boolean 형의 적용 차이를 확인해야 하므로 BOOL_TRUE 선택 시 Boolean true 를 전달한다.
//  · wframe 은 Boolean 타입이므로 gdl_boolean 라벨(getText)을 Boolean 으로 변환하여 전달한다.
scwin.buildOptions = function () {
    let options = {};

    let vModal = par_useModalDisable.getValue();
    if (vModal === "BOOL_TRUE") {
        options.useModalDisable = true;
    } else if (vModal !== "") {
        options.useModalDisable = vModal;
    }

    let vWframe = par_wframe.getText();
    if (vWframe === "true") {
        options.wframe = true;
    } else if (vWframe === "false") {
        options.wframe = false;
    }

    return options;
}



// readCSV 실행
//  · 설정한 옵션값을 그대로 되출력하지 않고, 실제로 열린 CSV 파일 선택 팝업창의 렌더 상태를 읽어 출력한다.
scwin.btn_readCSV_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    target1.readCSV(scwin.buildOptions());

    setTimeout(scwin.printUploadState, 1200);
}



// 실제로 열린 CSV 파일 선택 팝업창의 document 를 반환한다.
//  · wframe 적용 시 화면 내 레이어(부모 문서), 미적용 시 window 이름 csvupWindow 인 별도 팝업창이다.
//  · 별도 팝업창은 로딩이 끝나기 전까지 about:blank 이므로 로딩 중임을 알린다.
scwin.getUploadDoc = function () {
    if (document.querySelector("input[name='filename']") !== null) {
        return { "doc" : document, "kind" : "화면 내 레이어(wframe)", "url" : document.location.href };
    }

    let objWin = window.open("", "csvupWindow");
    if (objWin === null || objWin.closed) return null;
    if (objWin.location.href === "about:blank") return { "loading" : true, "win" : objWin };

    return { "doc" : objWin.document, "kind" : "별도 팝업창", "url" : objWin.location.href };
}



// 실제로 열린 CSV 파일 선택 팝업창의 형태와 부모창 비활성화(모달) 레이어 상태를 출력한다.
//  · wframe 적용 시 화면 내 레이어로, 미적용 시 window 이름 csvupWindow 인 별도 팝업창으로 열린다.
//  · 부모창 비활성화는 부모 문서에 렌더된 모달 레이어(div.w2modal)의 표시 개수로 확인한다.
scwin.printUploadState = function (nRetry) {
    let bottom = wf_body_bottom.getObj("scwin");
    nRetry = nRetry || 0;

    let objInfo = scwin.getUploadDoc();

    if (objInfo !== null && objInfo.loading === true) {
        if (nRetry < 6) {
            setTimeout(function () { scwin.printUploadState(nRetry + 1); }, 500);
            return;
        }
        objInfo.win.close();
        objInfo = null;
    }

    let strKind = (objInfo === null) ? "열려있지 않음" : objInfo.kind;
    let strUrl = (objInfo === null) ? "" : objInfo.url;

    let objList = document.querySelectorAll("div.w2modal");
    let nVisible = 0;
    for (let i = 0; i < objList.length; i++) {
        let objStyle = getComputedStyle(objList[i]);
        if (objStyle.display !== "none" && objStyle.visibility !== "hidden") nVisible++;
    }

    bottom.setReturnValue("팝업창 종류 : " + strKind + (strUrl === "" ? "" : " / 실제 열린 경로 : " + strUrl));
    bottom.setReturnValue("부모창 모달(비활성화) 레이어 : 전체 " + objList.length + "개 / 표시 " + nVisible + "개");
}



// 업로드 결과 확인 : GridView 에 반영된 데이터를 출력한다.
scwin.btn_getResult_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====btn_getResult_onclick=====");

    let cnt = target1.getRowCount();
    bottom.setReturnValue("Row 수 : " + cnt);
    for (let i = 0; i < cnt; i++) {
        bottom.setReturnValue("[" + i + "] " + target1.getCellData(i, "col1") + " | " + target1.getCellData(i, "col2") + " | " + target1.getCellData(i, "col3") + " | " + target1.getCellData(i, "col4"));
    }
}
